import { chromium } from 'playwright';
const LTR_RUN = /[A-Za-z][A-Za-z0-9+.-]*:\/\/[A-Za-z0-9:\/?&=._%+-]*|[A-Za-z0-9][A-Za-z0-9 .,:×x\/()+_-]*[A-Za-z0-9)]|[A-Za-z0-9]/g;
function build(str){
  let out='', cursor=0;
  for (const m of str.matchAll(LTR_RUN)){
    const i=m.index;
    if(i>cursor) out+=esc(str.slice(cursor,i));
    out+=`<bdi class="ltr-run">${esc(m[0])}</bdi>`;
    cursor=i+m[0].length;
  }
  if(cursor<str.length) out+=esc(str.slice(cursor));
  return out;
}
const esc=s=>s.replace(/&/g,'&amp;').replace(/</g,'&lt;');
const samples = [
  'هدف البروتين: 131–180 غ/يوم',
  'اختر 5–10 دقائق، ثم اضغط تم.',
  'علوي/سفلي — الكتلة أ (أسابيع 1–4)',
  'الصدر يتجاوز الحد الصارم 10–20 مجموعة.',
  'الأسبوعان 1–2 = تدرّج عودة',
  'الحجم 4,658 كغ',
];
const b = await chromium.launch();
const p = await b.newPage();
await p.setContent(`<!doctype html><html lang="ar" dir="rtl"><head><style>.ltr-run{direction:ltr;unicode-bidi:isolate}body{font:16px sans-serif}div{margin:4px}</style></head><body>${samples.map((s,i)=>`<div id="d${i}">${build(s)}</div>`).join('')}</body></html>`);
for (let i=0;i<samples.length;i++){
  // read visual order by measuring bounding boxes of each child
  const info = await p.evaluate((id)=>{
    const el = document.getElementById(id);
    const parts=[];
    for (const n of el.childNodes){
      const r = document.createRange(); r.selectNodeContents(n.nodeType===3?n:n);
      if(n.nodeType===3){ r.selectNode(n); } else { r.selectNode(n); }
      const rect = r.getBoundingClientRect();
      parts.push({text:n.textContent, x:Math.round(rect.x), w:Math.round(rect.width)});
    }
    return {src: el.textContent, parts};
  }, 'd'+i);
  const visual = info.parts.filter(p=>p.text.trim()).sort((a,b)=>a.x-b.x).map(p=>p.text.trim()).join(' | ');
  console.log('SRC :', samples[i]);
  console.log('LTR-visual-order(left→right):', visual);
  console.log('---');
}
await b.close();
